416	  // against the checkout's repository while every READ went to `repos//issues/...` and
417	  // came back 404. The dispatch then reported `refused-outstanding`, which is the one
418	  // answer that looks benign: the log says the node already had an agent asked for it,
419	  // and no run is started. `gh` fills the placeholder in from the checkout, which is
420	  // the same repository the POST reached.
421	  const repoPath = d.repo ?? "{owner}/{repo}";
422	  const removeMarker = (): void => {
